def answer_bag_behind_girl(image):
    image_patch = ImagePatch(image)
    girl_patches = image_patch.find("girl")

    if not girl_patches:
        return "No girl found in the image."

    girl_patch = girl_patches[0]
    girl_center_x = (girl_patch.left + girl_patch.right) / 2

    bags = []
    for obj in ["bag"]:
        obj_patches = image_patch.find(obj)
        for obj_patch in obj_patches:
            obj_center_x = (obj_patch.left + obj_patch.right) / 2
            if obj_center_x < girl_center_x:
                bags.append(obj_patch)

    if not bags:
        return "No bag found behind the girl."

    closest_bag = min(bags, key=lambda bag: abs(girl_center_x - ((bag.left + bag.right) / 2)))
    return closest_bag.llm_query("What is the color of the bag?", long_answer=False)

